{"cards": [{"node_code": "N_25dfeea85eaf0fc1", "definition": "研究生物体内嘌呤和嘧啶核苷酸的合成、分解代谢途径，及其在核酸合成、能量传递和信号转导中的生化机制。", "boundary": "本节点聚焦于核苷酸作为小分子物质的化学转化过程，包括从头合成、补救合成及降解产物（如尿酸）的代谢。不涵盖DNA/RNA的复制、转录等遗传信息传递过程，也不涵盖核苷酸类似物作为药物的具体临床药理作用，除非直接关联其代谢机制。", "includes": ["嘌呤与嘧啶核苷酸的从头合成与补救合成途径", "核苷酸分解代谢及终产物（如尿酸）的排泄机制", "核苷酸代谢异常导致的生化基础（如痛风、Lesch-Nyhan综合征的生化机制）"], "excludes": ["核酸（DNA/RNA）的生物合成与复制机制", "核苷酸类似物药物的临床药代动力学与药效学"], "sibling_distinctions": [{"other_code": "N_b23e7f821b12a5cb", "rule": "糖代谢关注葡萄糖等单糖的氧化分解与合成，本节点关注含氮碱基核苷酸的合成与分解。"}, {"other_code": "N_37e98d93abebcab9", "rule": "脂质代谢关注脂肪酸、甘油三酯等的转化，本节点关注核苷酸骨架及碱基的代谢。"}, {"other_code": "N_78a50406dba08a9c", "rule": "氨基酸代谢关注蛋白质的基本单位，本节点关注核酸的基本单位，两者在代谢网络中相互独立但存在交叉（如转氨作用）。"}, {"other_code": "N_ae846c84b293f92a", "rule": "本节点聚焦于核苷酸这一特定类别物质的具体代谢途径，整合与调节节点关注各类代谢途径之间的整体协调与调控机制。"}], "cross_boundary_rule": "若研究聚焦于核苷酸代谢酶缺陷导致的特定遗传病生化机制，主挂载本节点；若研究核苷酸代谢与其他代谢途径（如糖、氨基酸）的整体协调，主挂载物质代谢的整合与调节。"}, {"node_code": "N_ae846c84b293f92a", "definition": "研究糖、脂、氨基酸、核苷酸等物质代谢途径之间的相互联系、整体协调及机体在不同生理状态下的代谢调节机制。", "boundary": "本节点聚焦于代谢网络的整体视角，包括激素调节、酶活性调控、代谢物互变及能量平衡。不涵盖单一物质（如仅糖或仅脂）的具体代谢步骤细节，除非用于说明整体调节逻辑。", "includes": ["糖、脂、氨基酸、核苷酸代谢途径的相互转化与联系", "激素（如胰岛素、胰高血糖素）对代谢的整体调节作用", "不同生理状态（如空腹、运动、应激）下的代谢适应与能量平衡"], "excludes": ["单一代谢途径中具体酶促反应的化学机制", "遗传信息传递与基因表达调控"], "sibling_distinctions": [{"other_code": "N_b23e7f821b12a5cb", "rule": "糖代谢节点关注糖的具体代谢步骤，本节点关注糖代谢与其他代谢途径的整体协调。"}, {"other_code": "N_37e98d93abebcab9", "rule": "脂质代谢节点关注脂的具体代谢步骤，本节点关注脂代谢与其他代谢途径的整体协调。"}, {"other_code": "N_78a50406dba08a9c", "rule": "氨基酸代谢节点关注氨基酸的具体代谢步骤，本节点关注氨基酸代谢与其他代谢途径的整体协调。"}, {"other_code": "N_25dfeea85eaf0fc1", "rule": "核苷酸代谢节点关注核苷酸的具体代谢步骤，本节点关注核苷酸代谢与其他代谢途径的整体协调。"}], "cross_boundary_rule": "若研究聚焦于特定代谢途径（如糖酵解）的具体步骤，主挂载对应物质代谢节点；若研究该途径如何受激素调节或与其他途径互变，主挂载本节点。"}]}
